// runCloserChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runCloserChecks(
	t *testing.T,
	cfg *closerConfig,
	label string,
	factory func() embedded.Closer,
	wrap func(tb testing.TB, subject embedded.Closer) embedded.Closer,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run("Close", func(t *testing.T) {
			t.Parallel()
			cfg.run(t, "Close/smoke", "smoke", func(tb testing.TB) {
				AssertCloserCloseSmoke(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/reports a cancelled context", "reports a cancelled context", func(tb testing.TB) {
				AssertCloserCloseCancels(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/reports an expired deadline", "reports an expired deadline", func(tb testing.TB) {
				AssertCloserCloseHonoursDeadline(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/tolerates a nil context", "tolerates a nil context", func(tb testing.TB) {
				AssertCloserCloseToleratesNilContext(tb, cfg.subject(tb, factory, wrap))
			})
			for _, c := range cfg.onClose {
				cfg.run(t, "Close"+"/"+c.name, c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through CloserWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

