// CloserSeed replaces the derived seed.
//
// For an interface with no writer to seed itself through, which is the one
// input a conformance run cannot derive: a reader over an empty subject
// asserts nothing.
//
// Returning an error rather than swallowing one. A seed that failed quietly
// leaves every check after it asserting nothing and reporting success.
func CloserSeed(fn func(ctx context.Context, subject embedded.Closer) error) CloserOption {
	return func(c *closerConfig) {
		c.seed = fn
	}
}

// CloserOnClose adds a named check to Close.
func CloserOnClose(name string, fn CloserCloseCheck) CloserOption {
	return func(c *closerConfig) {
		c.onClose = append(c.onClose, namedCloserCloseCheck{name, fn})
	}
}

// CloserWithout drops generated checks by the path each reports under.
//
// For a subject that legitimately violates one. Without this the only recourse
// is to stop running the suite, which costs every other check in the file — so
// a dropped check is reported as skipped rather than silently omitted.
func CloserWithout(paths ...string) CloserOption {
	return func(c *closerConfig) {
		for _, p := range paths {
			c.without[p] = struct{}{}
		}
	}
}

type namedCloserCloseCheck struct {
	name string
	fn   CloserCloseCheck
}

type namedCloserSubject struct {
	name    string
	factory func() embedded.Closer
}

// closerContractExtension is a body of checks a generated sibling adds through an option.
//
// A sibling declares the option and closes over whatever configures it, so
// everything that varies per run is typed and private to the file that owns it
// — this file understands only the name and the call. Nothing arrives except
// through an option, which is what keeps the set fixed before the first subtest
// starts.
type closerContractExtension struct {
	// name is the path this reports under, and the one CloserWithout drops
	// it by. Anything nested beneath it is the extension's own to name.
	name string

	// run takes the factory rather than a subject. One that drives sequences
	// builds a subject per iteration, and one that compares against a reference
	// needs the unseeded subject a factory returns — which
	// closerConfig.subject is not.
	//
	// Called once per subject, in parallel, sharing the config. Anything it
	// mutates has to be built inside the call: state captured when the option
	// was declared is state two subjects write at once.
	run func(
		t *testing.T,
		subject string,
		factory func() embedded.Closer,
		cfg *closerConfig,
	)
}

type closerConfig struct {
	Fixture       CloserFixture
	subjects      []namedCloserSubject
	withoutDouble bool
	clock         clock.Clock
	seed          func(ctx context.Context, subject embedded.Closer) error
	without       map[string]struct{}
	extensions    []closerContractExtension
	onClose       []namedCloserCloseCheck
}

func newCloserConfig(opts ...CloserOption) *closerConfig {
	c := &closerConfig{
		Fixture: DefaultCloserFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	for _, o := range opts {
		o(c)
	}
	return c
}

// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *closerConfig) subject(
	tb testing.TB,
	factory func() embedded.Closer,
	wrap func(tb testing.TB, subject embedded.Closer) embedded.Closer,
) embedded.Closer {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			tb.Fatalf("the seed supplied through CloserSeed failed: %v", err)
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through CloserWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *closerConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// closerPaths is every path this file reports a check under.
//
// The set a CloserWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var closerPaths = map[string]struct{}{
	"Close/smoke":                       {},
	"Close/reports a cancelled context": {},
	"Close/reports an expired deadline": {},
	"Close/tolerates a nil context":     {},
}

// phantoms names every CloserWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *closerConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := closerPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onClose {
			if "Close"+"/"+on.name == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *closerConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through CloserWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

// ComposedGetCheck is one assertion about Get.
//
// Every generated check for Get is a value of it, and so is one you
// write — so they compose, reorder, and each runs standalone. testing.TB rather
// than *testing.T is what lets a stand-in drive it and prove it can fail.
type ComposedGetCheck func(tb testing.TB, subject embedded.Composed, key string)

// ComposedPingCheck is one assertion about Ping.
//
// Every generated check for Ping is a value of it, and so is one you
// write — so they compose, reorder, and each runs standalone. testing.TB rather
// than *testing.T is what lets a stand-in drive it and prove it can fail.
type ComposedPingCheck func(tb testing.TB, subject embedded.Composed)

// ComposedCloseCheck is one assertion about Close.
//
// Every generated check for Close is a value of it, and so is one you
// write — so they compose, reorder, and each runs standalone. testing.TB rather
// than *testing.T is what lets a stand-in drive it and prove it can fail.
type ComposedCloseCheck func(tb testing.TB, subject embedded.Composed)

// ComposedFixture holds every input the generated checks run against.
//
// Derived from each method's parameter names and types. Every field has a
// companion holding a second, different value: a check comparing a result
// against a single input passes whenever the subject happened to be seeded with
// it, and a miss check whose key happens to hit asserts nothing.
//
// A field whose type admits no literal — a func, a channel, a type from a
// package this run never read — is declared and left at its zero value, and
// every generated check that needed it was dropped rather than emitted against
// a value nobody could write. Supply one through ComposedWithFixture
// and the check a consumer writes has something to use.
type ComposedFixture struct {
	Key      string
	KeyOther string
}

// DefaultComposedFixture is what this run derived. Replace any field through
// ComposedWithFixture; the rest keep these values.
func DefaultComposedFixture() ComposedFixture {
	return ComposedFixture{
		Key:      "test-key",
		KeyOther: "other-key",
	}
}

// AssertComposedContract runs every generated check against every declared subject.
//
//	Checks:   13 across 3 methods, per subject
//	Subjects: declare each with ComposedSubject
//	Double:   every subject runs a second time wrapped in ComposedStub, so
//	          anything the wrapper fails that the subject passes is the double
//	          lying. ComposedWithoutDouble declines it.
//	Extend:   ComposedOnGet, ComposedOnPing, ComposedOnClose
//	Drop:     ComposedWithout, by the path each check reports under
//
// # What this file does not check
//
// The interface declares these and nothing here asserts them. Each is statable
// against a subject you can build, so the check is yours to write:
//
//   - lifecycle, on Ping, Close — write it with ComposedOnPing
func AssertComposedContract(t *testing.T, opts ...ComposedOption) {
	t.Helper()
	cfg := newComposedConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertComposedContract was given no subject; declare one with " +
			"ComposedSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("ComposedWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runComposedChecks(t, cfg, s.name, s.factory, nil)
		if !cfg.withoutDouble {
			runComposedChecks(t, cfg, s.name+" through the double", s.factory,
				func(tb testing.TB, subject embedded.Composed) embedded.Composed {
					return NewComposedStub(tb, ComposedStubDelegateTo(subject))
				})
		}
	}
}

// runComposedChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runComposedChecks(
	t *testing.T,
	cfg *composedConfig,
	label string,
	factory func() embedded.Composed,
	wrap func(tb testing.TB, subject embedded.Composed) embedded.Composed,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run("Get", func(t *testing.T) {
			t.Parallel()
			cfg.run(t, "Get/smoke", "smoke", func(tb testing.TB) {
				AssertComposedGetSmoke(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
			})
			cfg.run(t, "Get/reports a cancelled context", "reports a cancelled context", func(tb testing.TB) {
				AssertComposedGetCancels(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
			})
			cfg.run(t, "Get/reports an expired deadline", "reports an expired deadline", func(tb testing.TB) {
				AssertComposedGetHonoursDeadline(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
			})
			cfg.run(t, "Get/tolerates a nil context", "tolerates a nil context", func(tb testing.TB) {
				AssertComposedGetToleratesNilContext(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
			})
			cfg.run(t, "Get/an error carries the zero value", "an error carries the zero value", func(tb testing.TB) {
				AssertComposedGetZeroOnError(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.KeyOther)
			})
			for _, c := range cfg.onGet {
				cfg.run(t, "Get"+"/"+c.name, c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		t.Run("Ping", func(t *testing.T) {
			t.Parallel()
			cfg.run(t, "Ping/smoke", "smoke", func(tb testing.TB) {
				AssertComposedPingSmoke(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Ping/reports a cancelled context", "reports a cancelled context", func(tb testing.TB) {
				AssertComposedPingCancels(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Ping/reports an expired deadline", "reports an expired deadline", func(tb testing.TB) {
				AssertComposedPingHonoursDeadline(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Ping/tolerates a nil context", "tolerates a nil context", func(tb testing.TB) {
				AssertComposedPingToleratesNilContext(tb, cfg.subject(tb, factory, wrap))
			})
			for _, c := range cfg.onPing {
				cfg.run(t, "Ping"+"/"+c.name, c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		t.Run("Close", func(t *testing.T) {
			t.Parallel()
			cfg.run(t, "Close/smoke", "smoke", func(tb testing.TB) {
				AssertComposedCloseSmoke(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/reports a cancelled context", "reports a cancelled context", func(tb testing.TB) {
				AssertComposedCloseCancels(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/reports an expired deadline", "reports an expired deadline", func(tb testing.TB) {
				AssertComposedCloseHonoursDeadline(tb, cfg.subject(tb, factory, wrap))
			})
			cfg.run(t, "Close/tolerates a nil context", "tolerates a nil context", func(tb testing.TB) {
				AssertComposedCloseToleratesNilContext(tb, cfg.subject(tb, factory, wrap))
			})
			for _, c := range cfg.onClose {
				cfg.run(t, "Close"+"/"+c.name, c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through ComposedWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

// AssertComposedGetSmoke asserts Get survives a call with derived inputs.
//
// Fails when: Get panics. The weakest check in this file and the one
// that catches the most — a method that panics on a derived value is one no
// other check here reaches.
func AssertComposedGetSmoke(tb testing.TB, subject embedded.Composed, key string) {
	tb.Helper()
	defer func() {
		if r := recover(); r != nil {
			tb.Fatalf("Get panicked on a derived value (%v); supply one it "+
				"accepts through ComposedWithFixture", r)
		}
	}()
	ctx := tb.Context()
	_, _ = subject.Get(ctx, key)
}

// AssertComposedGetCancels asserts Get reports a cancelled context as cancelled.
//
// Fails when: Get returns nil for a context cancelled before the
// call, or returns an error that does not answer to context.Canceled. Both
// matter and they are different defects: the first is work done that the caller
// asked not to be, the second is a caller who wrote
// `errors.Is(err, context.Canceled)` and gets false for a call that was.
//
// The error rather than merely its presence is what separates this from the
// deadline check. Asserting only that something came back makes the two one
// check written twice.
func AssertComposedGetCancels(tb testing.TB, subject embedded.Composed, key string) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	_, err := subject.Get(ctx, key)
	testkit.ErrorIs(tb, err, context.Canceled,
		"Get must report a cancelled context as context.Canceled")
}

// AssertComposedGetHonoursDeadline asserts Get reports an expired deadline as exceeded.
//
// Fails when: Get returns nil for a context whose deadline has
// passed, or returns an error that does not answer to
// context.DeadlineExceeded. Distinct from cancellation in what the caller
// learns: a cancelled call was called off, an expired one ran out of time, and
// only the second is worth retrying.
//
// The deadline is the zero time, which is unconditionally in the past. No clock
// is read: a generated check that consults the wall clock is one whose subject
// is partly the machine it runs on.
func AssertComposedGetHonoursDeadline(tb testing.TB, subject embedded.Composed, key string) {
	tb.Helper()
	ctx, cancel := context.WithDeadline(tb.Context(), time.Time{})
	defer cancel()
	_, err := subject.Get(ctx, key)
	testkit.ErrorIs(tb, err, context.DeadlineExceeded,
		"Get must report an expired deadline as context.DeadlineExceeded")
}

// AssertComposedGetToleratesNilContext asserts Get does not panic on a nil context.
//
// Fails when: Get panics. Returning an error is correct and
// succeeding is correct — a nil context reaches production through a caller
// that forgot one, and a panic turns that into an outage rather than a failed
// request.
func AssertComposedGetToleratesNilContext(tb testing.TB, subject embedded.Composed, key string) {
	tb.Helper()
	defer func() {
		if r := recover(); r != nil {
			tb.Errorf("Get panicked on a nil context (%v); return an error instead", r)
		}
	}()
	//nolint:staticcheck // passing nil is the check.
	var ctx context.Context
	_, _ = subject.Get(ctx, key)
}

// AssertComposedGetZeroOnError asserts an error is accompanied by the zero value.
//
// Fails when: Get returns a non-zero result alongside a non-nil
// error. A caller who checks the error and a caller who checks the value must
// not disagree about whether the call succeeded.
//
// Skips when the alternate input succeeds: a total method has no failure this
// run can reach, and a skip says so where a green line would claim a
// comparison that never happened.
func AssertComposedGetZeroOnError(tb testing.TB, subject embedded.Composed, key string) {
	tb.Helper()
	ctx := tb.Context()
	r0, r1 := subject.Get(ctx, key)
	if r1 == nil {
		tb.Skipf("Get accepted the alternate input; nothing this run " +
			"supplies makes it fail, so the zero-on-error claim goes unexercised")
		return
	}
	{
		var zero string
		testkit.Equal(tb, r0, zero,
			"Get must return the zero value alongside an error")
	}
}

