// ComposedOption configures a contract run.
type ComposedOption func(*composedConfig)

// ComposedSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func ComposedSubject(name string, factory func() embedded.Composed) ComposedOption {
	return func(c *composedConfig) {
		c.subjects = append(c.subjects, namedComposedSubject{name, factory})
	}
}

// ComposedWithoutDouble declines the second run through ComposedStub.
//
// The double run proves the stand-in is faithful, and costs a second pass over
// every check. Decline it where the double is not used.
func ComposedWithoutDouble() ComposedOption {
	return func(c *composedConfig) { c.withoutDouble = true }
}

